    editorAgentEmpty: "Tell me how you want this timeline adjusted — tighten pacing, move or trim clips, add tracks, or change the picture; edits go through confirmation cards.",
    editorAgentPlaceholder: "e.g. shorten each of the first three clips by 0.5 seconds, then close the gaps",
    editorAgentContext:
      "You are assisting with timeline \"{sequence}\" in Mosael project \"{project}\" (project_id={projectId}, sequence_id={sequenceId}). Call inspect_sequence first to read the current tracks and clips; use list_assets when you need workspace media. All changes must use edit_timeline with granular operations (insert_clip/move_clip/trim_clip/delete_clip/cut_clip_range/add_track/remove_track/set_clip_effects/set_clip_transform); do not use edit_workflow. Changes create a confirmation card for my approval.",
    boardAgentEmpty: "Tell me what you want on this board — lay out an idea, add empty slots, wire them up; changes go through confirmation cards.",
    boardAgentPlaceholder: "e.g. break this into six shot notes, each followed by an image slot",
    boardAgentContext:
      "You are assisting with Mosael creative board \"{name}\" (board_id={id}). Call get_board first, then edit_board with granular ops (add_item/set_text/set_color/move_item/resize_item/connect/remove_item/remove_edge, batchable; the server applies them to the current canvas so you never rewrite the whole board — the user arranged those positions by hand). An image/video/audio item with no asset_id is an EMPTY SLOT the user writes a prompt on and generates; setting up slots and wiring references is often more useful than deciding the content for them. A board is not a workflow — do not use edit_workflow on it. Changes create a confirmation card for my approval.",
    wfAgentPlaceholder: "e.g. add a condition branch; if search is empty, notify via HTTP",
    wfAgentAttach: "Attach file",
    wfAgentAttached: "attachment",
    wfAgentContext: "You are assisting with Mosael workflow \"{name}\" (workflow_id={id}). Use get_workflow to inspect and list_workflow_node_types for node specs. Prefer edit_workflow for changes — submit granular ops (add_node/connect/connect_data/set_node_config/remove_node, batchable; the server applies them to the current graph so you never rewrite the whole thing). Deleting workflow nodes also must use edit_workflow/remove_node; do not use edit_timeline. The start node can be deleted too; the workflow is saved as a draft and cannot run until a start node is added again. Use update_workflow only to rename or replace the entire graph. Both create a confirmation card for my approval.",
