    permTraceGateBypass: "approved by bypass mode",
    permTraceGateSessionAllow: "you chose “always allow in this chat”",
    permModeBypassConfirmTitle: "Turn on \u201CApprove everything\u201D?",
    permModeBypassConfirmBody:
      "In this conversation the agent will stop asking for your consent to anything \u2014 including publishing under your account, calling external services, and running code on this machine. Those consequences are not inside Mosael and cannot be undone. Every action is still recorded.",
    permModeBypassConfirmCta: "I understand, turn it on",
    autopilotTitle: "Auto-approve rules",
    autopilotDesc:
      "When a conversation is set to auto-approve, these three kinds of irreversible action are decided here. The default is to always ask you; switch one to \"let the judge decide\" and a separate model call — blind to the conversation — decides whether to allow or ask. If it cannot tell, times out, or errors, it asks you. Notes can only tighten it; they can never allow anything on their own. Admins only.",
    autopilotHttp: "Outbound requests",
    autopilotHttpDesc: "Write requests to someone else's server — once sent, they cannot be taken back.",
    autopilotPublish: "Publishing",
    autopilotPublishDesc: "A publish card carries only an asset id, so the judge cannot see what is being posted — turning this on hands it that call too.",
    autopilotGateAsk: "Always ask me",
    autopilotGateJudge: "Let the judge decide",
    autopilotGateAlways: "Always allow",
    autopilotRunCode: "Running code in the sandbox",
    autopilotRunCodeDesc: "Runs in an isolated container with no network and no access to your files. \u201CIs this snippet safe\u201D has no enumerable criterion, so it asks every time by default.",
    autopilotRunHostCode: "Running code on this computer",
    autopilotRunHostCodeDesc: "Runs directly on your computer with access to your files and local programs. Desktop app only; allowed separately from the sandbox.",
    autopilotBlender: "Modeling in Blender",
    autopilotBlenderDesc: "The agent runs modeling code in your Blender. A modeling session often takes dozens of steps, so this can be allowed on its own; an undo step is pushed first. It is still local code, not a sandbox.",
    autopilotNotes: "Extra guidance",
    autopilotNotesDesc: "Your own words, passed to the judge verbatim. It can only narrow — it cannot allow anything on its own.",
    autopilotNotesPlaceholder: "e.g. only post to drafts; never call an endpoint containing \u201Cdelete\u201D.",
    autopilotJudgeTitle: "The judge",
    autopilotJudgeDesc:
      "Cases the lists do not cover go to a separate model call. It receives only the tool name, this call's arguments and the rules above — not the conversation, and not the pages and documents tools returned, which is exactly where outside text could sway a decision. Timeouts, errors and unreadable answers all fall back to asking you.",
    autopilotJudgeBadge: "isolated from the conversation",
